      return {
        id: radio.id,
        hasLabel: !!label,
        labelText: label ? label.textContent.trim() : null
      };
    });

    expect(radioLabels).toEqual([
      { id: 'notification-email', hasLabel: true, labelText: 'Email' },
      { id: 'notification-sms', hasLabel: true, labelText: 'SMS' },
      { id: 'notification-push', hasLabel: true, labelText: 'Push Notifications' }
    ]);
  });

  test('All radios should share same name attribute', () => {
    const names = Array.from(document.querySelectorAll('input[type="radio"]')).map(radio => radio.name);

