    expect(allSameName).toBe(true);
    expect(names[0]).toBe('notification-preference');
  });

  test('Form should have fieldset and legend', () => {
    const hasFieldset = !!document.querySelector('fieldset');
    const hasLegend = !!document.querySelector('legend');

    expect(hasFieldset).toBe(true);
    expect(hasLegend).toBe(true);
  });

  test('Submit button should be accessible', () => {
    const button = document.querySelector('button[type="submit"]');

    expect(button.type).toBe('submit');
    expect(button.textContent.trim()).toBe('Save Preferences');
  });

  test('All required radios should have required attribute', () => {
    const radios = Array.from(document.querySelectorAll('input[name="notification-preference"]')).map(input => ({
      id: input.id,
      required: input.required
    }));

    radios.forEach(radio => {
      expect(radio.required).toBe(true);
    });
  });

  test('Page should have proper heading hierarchy', () => {
    const h1s = document.querySelectorAll('h1');

    expect(h1s.length).toBe(1);
    expect(h1s[0].textContent).toBe('Account Settings');
  });

  test('Page should have main landmark', () => {
    const hasMain = !!document.querySelector('main');
    expect(hasMain).toBe(true);
  });

  test('Skip link should be present and functional', () => {
    const skipLink = document.querySelector('a.skip-link');

    expect(skipLink).not.toBeNull();
    expect(skipLink.getAttribute('href')).toBe('#main-content');
    expect(skipLink.textContent).toBe('Skip to main content');
  });

  test('Form should have proper structure', () => {
